```json
{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT COUNT(*) n, approx_quantile(c.duration::DOUBLE/1e6,0.5) client_med_ms, approx_quantile(s.duration::DOUBLE/1e6,0.5) seat_server_med_ms, approx_quantile(c.duration::DOUBLE/1e6 - s.duration::DOUBLE/1e6,0.5) gap_med_ms, approx_quantile(c.duration::DOUBLE/1e6 - s.duration::DOUBLE/1e6,0.95) gap_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server'",
          "claim": "In the incident, travel-plan's client calls to seat-service take ~2.3 s extra on the wire, while seat's server time stays ~17 ms."
        },
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'norm' ph, * FROM normal_traces) SELECT COUNT(*) n, approx_quantile(c.duration::DOUBLE/1e6,0.5) client_med_ms, approx_quantile(s.duration::DOUBLE/1e6,0.5) seat_server_med_ms, approx_quantile(c.duration::DOUBLE/1e6 - s.duration::DOUBLE/1e6,0.5) gap_med_ms, approx_quantile(c.duration::DOUBLE/1e6 - s.duration::DOUBLE/1e6,0.95) gap_p95_ms FROM t c JOIN t s ON s.parent_span_id = c.span_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server'",
          "claim": "In the normal period the same travel-plan to seat call gap is about 3 ms, so the 2.3 s gap is new."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, COUNT(*) n, approx_quantile(c.duration::DOUBLE/1e6 - s.duration::DOUBLE/1e6,0.5) gap_med_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='ts-travel2-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Other callers of seat-service (travel2) show only ~4 ms gap, so the delay is specific to the travel-plan to seat connection."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' ph, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT ph, service_name, span_name, COUNT(*) n, approx_quantile(duration::DOUBLE/1e6,0.5) med_ms, approx_quantile(duration::DOUBLE/1e6,0.95) p95_ms FROM t WHERE attr_span_kind='Server' AND span_name LIKE '%travelPlan%' AND service_name IN ('ts-travel-plan-service','ts-ui-dashboard') GROUP BY 1,2,3 ORDER BY 3,1",
          "claim": "travelPlan endpoints on ts-travel-plan-service and ts-ui-dashboard both rise from ~0.4 s median to ~12 s median during the incident."
        }
      ]
    }
  ]
}
```

